1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { ComissaoService } from './comissao.service';
4	import { GeocodingService } from './geocoding.service';
5	import { EstoqueService } from '../estoque/estoque.service';
6	import { SalaoService } from '../salao/salao.service';
7	import { EMAIL_RE, PHONE_RE } from './motoboy-auth.service';
8	
9	export interface MotoboyPeloRestauranteBody {
10	  name?: string;
11	  phone?: string;
12	  email?: string;
13	  password?: string;
14	}
15	
16	const DOC_BUCKET = 'motoboy-documentos';
17	const SIGNED_URL_TTL = 60 * 10; // 10 min
18	
19	@Injectable()
20	export class MotoboyService {
21	  constructor(
22	    private supabase: SupabaseService,
23	    private comissao: ComissaoService,
24	    private geocoding: GeocodingService,
25	    private estoque: EstoqueService,
26	    private salaoService: SalaoService,
27	  ) {}
28	
29	  // Antes de ver/solicitar vaga em qualquer estabelecimento, a plataforma
30	  // (admin) precisa ter revisado e aprovado o cadastro do motoboy.
31	  private async exigirAprovacaoPlataforma(motoboyId: number) {
32	    const { data } = await this.supabase.client
33	      .from('motoboys')
34	      .select('status_plataforma')
35	      .eq('id', motoboyId)
36	      .maybeSingle();
37	    if (data?.status_plataforma !== 'aprovado') {
38	      throw new ForbiddenException('Seu cadastro ainda está em análise pela plataforma. Aguarde a aprovação pra ver os estabelecimentos.');
39	    }
40	  }
41	
42	  private async exigirAfiliacaoAceita(motoboyId: number, restaurantId: number) {
43	    const { data } = await this.supabase.client
44	      .from('motoboy_estabelecimentos')
45	      .select('id, bloqueado')
46	      .eq('motoboy_id', motoboyId)
47	      .eq('restaurant_id', restaurantId)
48	      .eq('status', 'aceito')
49	      .maybeSingle();
50	    if (!data) throw new ForbiddenException('Motoboy não está afiliado a este estabelecimento');
51	    if (data.bloqueado) throw new ForbiddenException('Motoboy está bloqueado neste estabelecimento');
52	  }
53	
54	  // Estabelecimento que optou por entregar por conta própria não deve aparecer
55	  // pra motoboys pegarem pedido sozinhos — o dono ainda pode atribuir manualmente
56	  // como exceção (não passa por aqui).
57	  private async exigirUsaMotoboy(restaurantId: number) {
58	    const { data } = await this.supabase.client
59	      .from('restaurants')
60	      .select('usa_motoboy')
61	      .eq('id', restaurantId)
62	      .maybeSingle();
63	    if (data && data.usa_motoboy === false) {
64	      throw new ForbiddenException('Este estabelecimento faz entregas por conta própria');
65	    }
66	  }
67	
68	  private async signedUrl(path: string | null | undefined): Promise<string | null> {
69	    if (!path) return null;
70	    const { data } = await this.supabase.client.storage.from(DOC_BUCKET).createSignedUrl(path, SIGNED_URL_TTL);
71	    return data?.signedUrl ?? null;
72	  }
73	
74	  // ── Lado restaurante: gestão de afiliados ──────────────────────────
75	
76	  async listar(restaurantId: number) {
77	    const { data, error } = await this.supabase.client
78	      .from('motoboy_estabelecimentos')
79	      .select('bloqueado, motoboy:motoboys(id, name, phone, foto_perfil_url, criado_por_restaurant_id)')
80	      .eq('restaurant_id', restaurantId)
81	      .eq('status', 'aceito');
82	    if (error) throw error;
83	
84	    const motoboys = await Promise.all(
85	      (data ?? []).map(async (row: any) => {
86	        const resto = row.motoboy ?? {};
87	        return {
88	          ...resto,
89	          foto_perfil_url: await this.signedUrl(resto.foto_perfil_url),
90	          bloqueado: row.bloqueado,
91	          gerenciado_por_mim: resto.criado_por_restaurant_id === restaurantId,
92	        };
93	      }),
94	    );
95	    return { motoboys };
96	  }
97	
98	  // Cadastro direto: o próprio estabelecimento registra um motoboy seu, sem
99	  // passar pelo autocadastro do app + aprovação da plataforma + solicitação de
100	  // afiliação — já nasce aprovado e afiliado (o restaurante está vouching por ele).
101	  // Cria uma conta Supabase Auth de verdade (não mais password_hash local) —
102	  // e-mail é obrigatório porque é a identidade de login.
103	  async criarPeloRestaurante(restaurantId: number, body: MotoboyPeloRestauranteBody) {
104	    this.validarDadosMotoboy(body, { exigirNome: true, exigirEmail: true, exigirSenha: true });
105	
106	    const { data: existente } = await this.supabase.client
107	      .from('motoboys')
108	      .select('id')
109	      .or(`email.eq.${body.email ?? ''},phone.eq.${body.phone ?? ''}`)
110	      .maybeSingle();
111	    if (existente) throw new ConflictException('Já existe um cadastro de motoboy com este telefone ou e-mail');
112	
113	    const { data: criado, error: authError } = await this.supabase.client.auth.admin.createUser({
114	      email: body.email,
115	      password: body.password,
116	      email_confirm: true,
117	      user_metadata: { name: body.name, role: 'motoboy' },
118	    });
119	    if (authError) {
120	      if (authError.status === 422 || authError.message?.toLowerCase().includes('already')) {
121	        throw new ConflictException('Já existe uma conta com este e-mail');
122	      }
123	      throw authError;
124	    }
125	
126	    const agora = new Date().toISOString();
127	
128	    const { data: motoboy, error } = await this.supabase.client
129	      .from('motoboys')
130	      .insert({
131	        user_id: criado.user.id,
132	        name: body.name!.trim(),
133	        phone: body.phone || null,
134	        email: body.email,
135	        precisa_completar_cadastro: false,
136	        status_plataforma: 'aprovado',
137	        aprovado_em: agora,
138	        criado_por_restaurant_id: restaurantId,
139	      })
140	      .select('id, name, phone, email')
141	      .single();
142	    if (error) throw error;
143	
144	    const { error: afilError } = await this.supabase.client
145	      .from('motoboy_estabelecimentos')
146	      .insert({ motoboy_id: motoboy.id, restaurant_id: restaurantId, status: 'aceito', solicitado_em: agora, respondido_em: agora });
147	    if (afilError) throw afilError;
148	
149	    return { ...motoboy, criado_por_restaurant_id: restaurantId, bloqueado: false, sessao_ativa: false, gerenciado_por_mim: true };
150	  }
151	
152	  private validarDadosMotoboy(
153	    body: MotoboyPeloRestauranteBody,
154	    opts: { exigirNome: boolean; exigirEmail: boolean; exigirSenha: boolean },
155	  ) {
156	    if (opts.exigirNome && !body.name?.trim()) throw new BadRequestException('Informe o nome do motoboy');
157	    if (opts.exigirEmail && !body.email) throw new BadRequestException('Informe o e-mail do motoboy');
158	    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
159	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
160	    if (opts.exigirSenha && (!body.password || body.password.length < 8)) {
161	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
162	    }
163	    if (!opts.exigirSenha && body.password && body.password.length < 8) {
164	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
165	    }
166	  }
167	
168	  private async exigirMotoboyGerenciadoPeloRestaurante(motoboyId: number, restaurantId: number) {
169	    const { data: mb } = await this.supabase.client
170	      .from('motoboys')
171	      .select('id, user_id, email, criado_por_restaurant_id')
172	      .eq('id', motoboyId)
173	      .maybeSingle();
174	    if (!mb) throw new NotFoundException('Motoboy não encontrado');
175	    if (mb.criado_por_restaurant_id !== restaurantId) {
176	      throw new ForbiddenException('Essa ação só é permitida em motoboys cadastrados diretamente por este estabelecimento');
177	    }
178	    return mb;
179	  }
180	
181	  async editarPeloRestaurante(motoboyId: number, restaurantId: number, body: MotoboyPeloRestauranteBody) {
182	    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
183	    this.validarDadosMotoboy(body, { exigirNome: false, exigirEmail: false, exigirSenha: false });
184	
185	    // Senha/e-mail agora vivem no Supabase Auth — troca via admin API. Quando o
186	    // e-mail muda, o trigger sync_user_profile_email já mantém motoboys.email
187	    // sincronizado (dispara em AFTER UPDATE OF email ON auth.users).
188	    if (mb.user_id && (body.password || (body.email && body.email !== mb.email))) {
189	      const payload: Record<string, any> = {};
190	      if (body.password) payload.password = body.password;
191	      if (body.email && body.email !== mb.email) {
192	        payload.email = body.email;
193	        payload.email_confirm = true;
194	      }
195	      const { error: authError } = await this.supabase.client.auth.admin.updateUserById(mb.user_id, payload);
196	      if (authError) throw authError;
197	    }
198	
199	    const campos: Record<string, any> = {};
200	    if (body.name !== undefined) campos.name = body.name.trim();
201	    if (body.phone !== undefined) campos.phone = body.phone || null;
202	    // E-mail só é escrito aqui se o motoboy não tem user_id (nunca migrou pro
203	    // Supabase Auth) — senão o trigger acima já cuida disso.
204	    if (!mb.user_id && body.email !== undefined) campos.email = body.email || null;
205	    if (Object.keys(campos).length === 0) return { ok: true };
206	
207	    const { error } = await this.supabase.client.from('motoboys').update(campos).eq('id', motoboyId);
208	    if (error) throw error;
209	    return { ok: true };
210	  }
211	
212	  // Link de definir/redefinir senha (pra copiar/mandar por WhatsApp) — gerado
213	  // via Admin API, não depende do envio de e-mail do Supabase.
214	  async gerarLinkRedefinicaoSenha(motoboyId: number, restaurantId: number, redirectTo?: string) {
215	    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
216	    if (!mb.user_id) throw new NotFoundException('Este motoboy ainda não tem conta migrada — edite e informe um e-mail primeiro.');
217	
218	    const { data, error } = await this.supabase.client.auth.admin.generateLink({
219	      type: 'recovery',
220	      email: mb.email,
221	      options: redirectTo ? { redirectTo } : undefined,
222	    });
223	    if (error) throw error;
224	    return { link: data.properties.action_link };
225	  }
226	
227	  // Mesmo mecanismo que o cliente já usa em "esqueci minha senha" — sem mailer
228	  // próprio, reaproveita o e-mail nativo do Supabase Auth.
229	  async enviarLinkRedefinicaoSenhaPorEmail(motoboyId: number, restaurantId: number, redirectTo?: string) {
230	    const mb = await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
231	    if (!mb.user_id) throw new NotFoundException('Este motoboy ainda não tem conta migrada — edite e informe um e-mail primeiro.');
232	
233	    const { error } = await this.supabase.client.auth.resetPasswordForEmail(mb.email, redirectTo ? { redirectTo } : undefined);
234	    if (error) throw error;
235	    return { ok: true };
236	  }
237	
238	  // Excluir de verdade só é seguro sem histórico de entregas (motoboy_comissoes
239	  // referencia motoboy_id com ON DELETE CASCADE — apagaria ganhos já registrados).
240	  // Com histórico, orientar a bloquear em vez de excluir.
241	  async excluirPeloRestaurante(motoboyId: number, restaurantId: number) {
242	    await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
243	
244	    const { count } = await this.supabase.client
245	      .from('motoboy_comissoes')
246	      .select('id', { count: 'exact', head: true })
247	      .eq('motoboy_id', motoboyId);
248	    if ((count ?? 0) > 0) {
249	      throw new BadRequestException('Este motoboy já tem entregas registradas — bloqueie em vez de excluir, pra não perder o histórico.');
250	    }
251	
252	    const { error } = await this.supabase.client.from('motoboys').delete().eq('id', motoboyId);
253	    if (error) throw error;
254	    return { ok: true };
255	  }
256	
257	  // Pausa o motoboy pra este restaurante (não pega/recebe pedidos daqui) sem
258	  // desfazer a afiliação — diferente de removerAfiliacao, que exige nova solicitação.
259	  async bloquearAfiliacao(motoboyId: number, restaurantId: number, bloqueado: boolean) {
260	    const { data, error } = await this.supabase.client
261	      .from('motoboy_estabelecimentos')
262	      .update({ bloqueado, updated_at: new Date().toISOString() })
263	      .eq('motoboy_id', motoboyId)
264	      .eq('restaurant_id', restaurantId)
265	      .eq('status', 'aceito')
266	      .select()
267	      .maybeSingle();
268	    if (error) throw error;
269	    if (!data) throw new NotFoundException('Afiliação não encontrada');
270	    return { ok: true, bloqueado };
271	  }
272	
273	  async listarSolicitacoes(restaurantId: number, status: 'pendente' | 'aceito' | 'recusado' = 'pendente') {
274	    // Pra pendente precisamos da ficha completa (docs via signed URL); pra histórico
275	    // (aceito/recusado) só o básico, evita gerar signed URL à toa por linha.
276	    const campos = status === 'pendente'
277	      ? 'motoboy:motoboys(id, name, phone, email, foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url)'
278	      : 'motoboy:motoboys(id, name, phone, email)';
279	
280	    const { data, error } = await this.supabase.client
281	      .from('motoboy_estabelecimentos')
282	      .select(`id, solicitado_em, respondido_em, motivo_recusa, ${campos}`)
283	      .eq('restaurant_id', restaurantId)
284	      .eq('status', status)
285	      .order(status === 'pendente' ? 'solicitado_em' : 'respondido_em', { ascending: status === 'pendente' });
286	    if (error) throw error;
287	
288	    if (status !== 'pendente') {
289	      return {
290	        solicitacoes: (data ?? []).map((row: any) => ({
291	          id: row.id,
292	          solicitado_em: row.solicitado_em,
293	          respondido_em: row.respondido_em,
294	          motivo_recusa: row.motivo_recusa,
295	          motoboy: row.motoboy,
296	        })),
297	      };
298	    }
299	
300	    const solicitacoes = await Promise.all(
301	      (data ?? []).map(async (row: any) => ({
302	        id: row.id,
303	        solicitado_em: row.solicitado_em,
304	        motoboy: {
305	          ...row.motoboy,
306	          foto_perfil_url: await this.signedUrl(row.motoboy?.foto_perfil_url),
307	          documento_frente_url: await this.signedUrl(row.motoboy?.documento_frente_url),
308	          documento_verso_url: await this.signedUrl(row.motoboy?.documento_verso_url),
309	          comprovante_endereco_url: await this.signedUrl(row.motoboy?.comprovante_endereco_url),
310	        },
311	      })),
312	    );
313	    return { solicitacoes };
314	  }
315	
316	  async contarSolicitacoesPendentes(restaurantId: number) {
317	    const { count, error } = await this.supabase.client
318	      .from('motoboy_estabelecimentos')
319	      .select('id', { count: 'exact', head: true })
320	      .eq('restaurant_id', restaurantId)
321	      .eq('status', 'pendente');
322	    if (error) throw error;
323	    return { count: count ?? 0 };
324	  }
325	
326	  async aceitarSolicitacao(id: number, restaurantId: number) {
327	    const { data, error } = await this.supabase.client
328	      .from('motoboy_estabelecimentos')
329	      .update({ status: 'aceito', respondido_em: new Date().toISOString(), updated_at: new Date().toISOString() })
330	      .eq('id', id)
331	      .eq('restaurant_id', restaurantId)
332	      .eq('status', 'pendente')
333	      .select()
334	      .maybeSingle();
335	    if (error) throw error;
336	    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
337	    return data;
338	  }
339	
340	  async recusarSolicitacao(id: number, restaurantId: number, motivo?: string) {
341	    const { data, error } = await this.supabase.client
342	      .from('motoboy_estabelecimentos')
343	      .update({
344	        status: 'recusado',
345	        motivo_recusa: motivo ?? null,
346	        respondido_em: new Date().toISOString(),
347	        updated_at: new Date().toISOString(),
348	      })
349	      .eq('id', id)
350	      .eq('restaurant_id', restaurantId)
351	      .eq('status', 'pendente')
352	      .select()
353	      .maybeSingle();
354	    if (error) throw error;
355	    if (!data) throw new NotFoundException('Solicitação não encontrada ou já respondida');
356	    return data;
357	  }
358	
359	  // Restaurante muda de ideia sobre uma solicitação recusada — volta pra "pendente"
360	  // pra reavaliar (limpa motivo/data da recusa anterior).
361	  async revisarSolicitacao(id: number, restaurantId: number) {
362	    const { data, error } = await this.supabase.client
363	      .from('motoboy_estabelecimentos')
364	      .update({
365	        status: 'pendente',
366	        motivo_recusa: null,
367	        respondido_em: null,
368	        updated_at: new Date().toISOString(),
369	      })
370	      .eq('id', id)
371	      .eq('restaurant_id', restaurantId)
372	      .eq('status', 'recusado')
373	      .select()
374	      .maybeSingle();
375	    if (error) throw error;
376	    if (!data) throw new NotFoundException('Solicitação recusada não encontrada');
377	    return data;
378	  }
379	
380	  async removerAfiliacao(motoboyId: number, restaurantId: number) {
381	    const { data, error } = await this.supabase.client
382	      .from('motoboy_estabelecimentos')
383	      .update({ status: 'removido', updated_at: new Date().toISOString() })
384	      .eq('motoboy_id', motoboyId)
385	      .eq('restaurant_id', restaurantId)
386	      .eq('status', 'aceito')
387	      .select()
388	      .maybeSingle();
389	    if (error) throw error;
390	    if (!data) throw new NotFoundException('Afiliação não encontrada');
391	    return { ok: true };
392	  }
393	
394	  async atribuir(pedidoId: number, restaurantId: number, motoboyId: number) {
395	    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
396	
397	    const { error } = await this.supabase.client
398	      .from('orders')
399	      .update({ motoboy_id: motoboyId, status: 'out_for_delivery', updated_at: new Date().toISOString() })
400	      .eq('id', pedidoId)
401	      .eq('restaurant_id', restaurantId);
402	    if (error) throw error;
403	    return { ok: true, status: 'out_for_delivery' };
404	  }
405	
406	  // ── Lado motoboy: buscar/solicitar afiliação ───────────────────────
407	
408	  async buscarEstabelecimentos(motoboyId: number, busca?: string) {
409	    await this.exigirAprovacaoPlataforma(motoboyId);
410	
411	    let query = this.supabase.client
412	      .from('restaurants')
413	      .select('id, name, address, logo_url')
414	      .eq('bloqueado', false)
415	      .order('name')
416	      .limit(50);
417	    if (busca) query = query.ilike('name', `%${busca}%`);
418	    const { data: restaurantes, error } = await query;
419	    if (error) throw error;
420	
421	    const ids = (restaurantes ?? []).map((r) => r.id);
422	    const { data: afiliacoes } = ids.length
423	      ? await this.supabase.client
424	          .from('motoboy_estabelecimentos')
425	          .select('restaurant_id, status')
426	          .eq('motoboy_id', motoboyId)
427	          .in('restaurant_id', ids)
428	      : { data: [] as any[] };
429	    const statusMap = Object.fromEntries((afiliacoes ?? []).map((a: any) => [a.restaurant_id, a.status]));
430	
431	    return {
432	      estabelecimentos: (restaurantes ?? []).map((r) => ({ ...r, status_afiliacao: statusMap[r.id] ?? null })),
433	    };
434	  }
435	
436	  async solicitarAfiliacao(motoboyId: number, restaurantId: number) {
437	    await this.exigirAprovacaoPlataforma(motoboyId);
438	
439	    const { data: existente } = await this.supabase.client
440	      .from('motoboy_estabelecimentos')
441	      .select('id, status')
442	      .eq('motoboy_id', motoboyId)
443	      .eq('restaurant_id', restaurantId)
444	      .maybeSingle();
445	
446	    if (existente) {
447	      if (existente.status === 'aceito') throw new ConflictException('Você já atende este estabelecimento');
448	      if (existente.status === 'pendente') throw new ConflictException('Solicitação já enviada, aguardando resposta');
449	      // recusado ou removido — reabre como pendente
450	      const { data, error } = await this.supabase.client
451	        .from('motoboy_estabelecimentos')
452	        .update({
453	          status: 'pendente',
454	          motivo_recusa: null,
455	          solicitado_em: new Date().toISOString(),
456	          respondido_em: null,
457	          updated_at: new Date().toISOString(),
458	        })
459	        .eq('id', existente.id)
460	        .select()
461	        .single();
462	      if (error) throw error;
463	      return data;
464	    }
465	
466	    const { data, error } = await this.supabase.client
467	      .from('motoboy_estabelecimentos')
468	      .insert({ motoboy_id: motoboyId, restaurant_id: restaurantId })
469	      .select()
470	      .single();
471	    if (error) throw error;
472	    return data;
473	  }
474	
475	  async minhasAfiliacoes(motoboyId: number) {
476	    const { data, error } = await this.supabase.client
477	      .from('motoboy_estabelecimentos')
478	      .select('id, status, motivo_recusa, solicitado_em, respondido_em, restaurant:restaurants(id, name, address, logo_url)')
479	      .eq('motoboy_id', motoboyId)
480	      .neq('status', 'removido')
481	      .order('solicitado_em', { ascending: false });
482	    if (error) throw error;
483	    return { afiliacoes: data ?? [] };
