662	  // Só permitido se não houver motoboy atribuído (evita marcar como entrega própria
663	  // um pedido que já está com um motoboy de verdade).
664	  async entregarProprio(
665	    pedidoId: number,
666	    restaurantId: number,
667	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
668	  ) {
669	    const { data: pedido } = await this.supabase.client
670	      .from('orders')
671	      .select('id, status, restaurant_id, motoboy_id, total, payment_method')
672	      .eq('id', pedidoId)
673	      .eq('restaurant_id', restaurantId)
674	      .maybeSingle();
675	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
676	    if (pedido.motoboy_id) throw new BadRequestException('Pedido já está atribuído a um motoboy');
677	
678	    const updatePayload: Record<string, any> = {
679	      status: 'delivered',
680	      entrega_propria: true,
681	      updated_at: new Date().toISOString(),
682	    };
683	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
684	
685	    const { error } = await this.supabase.client.from('orders').update(updatePayload).eq('id', pedidoId);
686	    if (error) throw error;
687	
688	    if (entregaPagamento) {
689	      const { data: caixa } = await this.supabase.client
690	        .from('caixas')
691	        .select('id, entradas')
692	        .eq('restaurant_id', restaurantId)
693	        .eq('status', 'aberto')
694	        .maybeSingle();
695	
696	      if (caixa) {
697	        const entradas = (caixa.entradas ?? []) as any[];
698	        const novas: any[] = [];
699	        const agora = new Date().toISOString();
700	
701	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
702	          novas.push({
703	            descricao: `Entrega própria pedido #${pedidoId} — dinheiro`,
704	            valor: entregaPagamento.dinheiro,
705	            meio: 'dinheiro',
706	            criado_em: agora,
707	          });
708	        }
709	        if ((entregaPagamento.pix ?? 0) > 0) {
710	          novas.push({
711	            descricao: `Entrega própria pedido #${pedidoId} — PIX`,
712	            valor: entregaPagamento.pix,
713	            meio: 'pix',
714	            criado_em: agora,
715	          });
716	        }
717	
718	        if (novas.length > 0) {
719	          await this.supabase.client.from('caixas').update({ entradas: [...entradas, ...novas] }).eq('id', caixa.id);
720	        }
721	      }
722	    }
723	
724	    // Idem confirmarEntrega: pedido pago em dinheiro no checkout, sem o dono reportar
725	    // via entregaPagamento — precisa creditar o caixa físico do mesmo jeito.
726	    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash') {
727	      await this.salaoService.registrarEntradaCaixa(restaurantId, `Venda delivery em dinheiro (entrega própria) - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
728	    }
729	
730	    return { ok: true, pedido_id: pedidoId, status: 'delivered', entrega_propria: true };
731	  }
