958	  // Perfil próprio (nome/telefone/foto) — e-mail não é editável por aqui, é a
959	  // identidade de login (Supabase Auth); troca de e-mail passa por
960	  // authService.updateEmail no frontend, e o trigger sync_user_profile_email
961	  // mantém motoboys.email em dia.
962	  async atualizarPerfilMotoboy(motoboyId: number, body: { name?: string; phone?: string; foto_perfil?: string }) {
963	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
964	
965	    const campos: Record<string, any> = {};
966	    if (body.name !== undefined) {
967	      if (!body.name.trim()) throw new BadRequestException('Nome não pode ficar em branco');
968	      campos.name = body.name.trim();
969	    }
