  async confirmarEntrega(
    pedidoId: number,
    motoboyId: number,
    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number; cartao?: number },
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status, restaurant_id, total, frete_cobrado, customer_id, payment_method')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    // Pagamento combinado (dinheiro + PIX + cartão em qualquer fração) — a soma das
    // frações precisa bater com o total do pedido, senão dinheiro "some"/"aparece"
    // do nada no caixa. Os outros métodos (exato/pix/cartao) já mandam o valor certo
    // num campo só, exceto "conforme" com troco, que intencionalmente manda mais que
    // o total (é o que o cliente entregou em mãos, não o valor da venda).
    if (entregaPagamento?.metodo === 'combinado') {
      const soma = (entregaPagamento.dinheiro ?? 0) + (entregaPagamento.pix ?? 0) + (entregaPagamento.cartao ?? 0);
      if (Math.abs(soma - pedido.total) > 0.01) {
        throw new BadRequestException('Soma dos valores não bate com o total do pedido');
      }
    }

    // Taxa do cartão é sempre recalculada no backend (não confia no valor vindo do
    // app) — mesma fórmula/config do módulo Salão (Config > "Taxa do cartão"). Incide
    // só sobre a fatia paga no cartão, não sobre o pedido inteiro — importante no
    // pagamento combinado, onde o cartão pode ser só parte do total.
    let taxaCartaoValor = 0;
    if ((entregaPagamento?.cartao ?? 0) > 0) {
      taxaCartaoValor = await this.salaoService.calcularTaxaCartao(pedido.restaurant_id, entregaPagamento!.cartao!, 'credit_card');
      entregaPagamento = { ...entregaPagamento, taxa_cartao_valor: taxaCartaoValor } as any;
    }

    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
    if (entregaPagamento) {
      updatePayload.entrega_pagamento = entregaPagamento;
      updatePayload.pago_em = new Date().toISOString();
    }

    const { error } = await this.supabase.client
      .from('orders')
      .update(updatePayload)
      .eq('id', pedidoId);
    if (error) throw error;

    // Registrar entrada(s) no caixa aberto
    if (entregaPagamento && pedido.restaurant_id) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, entradas')
        .eq('restaurant_id', pedido.restaurant_id)
        .eq('status', 'aberto')
        .maybeSingle();

      if (caixa) {
        const entradas = (caixa.entradas ?? []) as any[];
        const novas: any[] = [];
        const agora = new Date().toISOString();

        if ((entregaPagamento.dinheiro ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — dinheiro`,
            valor: entregaPagamento.dinheiro,
            meio: 'dinheiro',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.pix ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — PIX`,
            valor: entregaPagamento.pix,
            meio: 'pix',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.cartao ?? 0) > 0) {
          novas.push({
            descricao: `Entrega pedido #${pedidoId} — Cartão${taxaCartaoValor > 0 ? ` (+ taxa ${taxaCartaoValor})` : ''}`,
            valor: (entregaPagamento.cartao ?? 0) + taxaCartaoValor,
            meio: 'cartao',
            criado_em: agora,
          });
        }

        if (novas.length > 0) {
          await this.supabase.client
            .from('caixas')
            .update({ entradas: [...entradas, ...novas] })
            .eq('id', caixa.id);
        }
      }
    }

    // Pedido já veio com "pagamento em dinheiro" escolhido no checkout (não é o motoboy
    // reportando o que cobrou na hora — isso é o `entregaPagamento` acima) — sem isso o
    // caixa físico nunca credita essa venda, só o fundo inicial (mesmo bug do salão).
    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash' && pedido.restaurant_id) {
      await this.salaoService.registrarEntradaCaixa(pedido.restaurant_id, `Venda delivery em dinheiro - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
    }

    // Calcula e registra a comissão do motoboy (idempotente — UNIQUE(pedido_id))
    await this.comissao.registrarComissaoEntrega(pedido, motoboyId);

    return { ok: true, pedido_id: pedidoId, status: 'delivered' };
  }

  // Dono do restaurante marca um pedido como entregue pela própria loja, sem motoboy.
  // Só permitido se não houver motoboy atribuído (evita marcar como entrega própria
  // um pedido que já está com um motoboy de verdade).
  async entregarProprio(
    pedidoId: number,
    restaurantId: number,
    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status, restaurant_id, motoboy_id, total, payment_method')
      .eq('id', pedidoId)
      .eq('restaurant_id', restaurantId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
    if (pedido.motoboy_id) throw new BadRequestException('Pedido já está atribuído a um motoboy');

    const updatePayload: Record<string, any> = {
      status: 'delivered',
      entrega_propria: true,
      updated_at: new Date().toISOString(),
    };
    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;

    const { error } = await this.supabase.client.from('orders').update(updatePayload).eq('id', pedidoId);
    if (error) throw error;

    if (entregaPagamento) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, entradas')
        .eq('restaurant_id', restaurantId)
        .eq('status', 'aberto')
        .maybeSingle();

      if (caixa) {
        const entradas = (caixa.entradas ?? []) as any[];
        const novas: any[] = [];
        const agora = new Date().toISOString();

        if ((entregaPagamento.dinheiro ?? 0) > 0) {
          novas.push({
            descricao: `Entrega própria pedido #${pedidoId} — dinheiro`,
            valor: entregaPagamento.dinheiro,
            meio: 'dinheiro',
            criado_em: agora,
          });
        }
        if ((entregaPagamento.pix ?? 0) > 0) {
          novas.push({
            descricao: `Entrega própria pedido #${pedidoId} — PIX`,
            valor: entregaPagamento.pix,
            meio: 'pix',
            criado_em: agora,
          });
        }

        if (novas.length > 0) {
          await this.supabase.client.from('caixas').update({ entradas: [...entradas, ...novas] }).eq('id', caixa.id);
        }
      }
    }

    // Idem confirmarEntrega: pedido pago em dinheiro no checkout, sem o dono reportar
    // via entregaPagamento — precisa creditar o caixa físico do mesmo jeito.
    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash') {
      await this.salaoService.registrarEntradaCaixa(restaurantId, `Venda delivery em dinheiro (entrega própria) - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
    }

    return { ok: true, pedido_id: pedidoId, status: 'delivered', entrega_propria: true };
  }

  async registrarOcorrencia(
    pedidoId: number,
    motoboyId: number,
    tipo: 'pendente' | 'cancelada',
    motivo: string,
  ) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, status')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    const update: Record<string, any> = {
      delivery_notes: motivo.trim(),
      delivery_occurrence: tipo,
      updated_at: new Date().toISOString(),
    };
    if (tipo === 'cancelada') update.status = 'canceled';

    const { error } = await this.supabase.client
      .from('orders')
      .update(update)
      .eq('id', pedidoId);
    if (error) throw error;

    if (tipo === 'cancelada' && pedido.status !== 'canceled') {
      await this.estoque.restaurarItensDoPedido(pedidoId);
    }

    return { ok: true, pedido_id: pedidoId, tipo, status: update.status ?? pedido.status };
  }

  async pedidosDisponiveis(motoboyId: number, restaurantId: number) {
    await this.exigirAfiliacaoAceita(motoboyId, restaurantId);
    await this.exigirUsaMotoboy(restaurantId);

    const { data, error } = await this.supabase.client
      .from('orders')
      .select('id, total, status, payment_method, created_at, customer_id')
      .eq('restaurant_id', restaurantId)
      .eq('status', 'ready')
      .is('motoboy_id', null)
      .order('created_at', { ascending: true });
    if (error) throw error;

    const pedidos = await Promise.all(
      (data ?? []).map(async (p) => {
        const { data: c } = p.customer_id
          ? await this.supabase.client
              .from('customers')
              .select('name, phone_e164, address_json')
              .eq('id', p.customer_id)
              .maybeSingle()
          : { data: null };
        const { data: itensRaw } = await this.supabase.client
          .from('order_items')
          .select('id, quantity, unit_price, product_id')
          .eq('order_id', p.id);
        return { ...p, cliente: c, itens: itensRaw ?? [] };
      }),
    );
    return { pedidos };
  }

  async pegarPedido(pedidoId: number, motoboyId: number) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, restaurant_id')
      .eq('id', pedidoId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado');
    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
    await this.exigirUsaMotoboy(pedido.restaurant_id);

    const { data, error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('restaurant_id', pedido.restaurant_id)
      .eq('status', 'ready')
      .is('motoboy_id', null)
      .select('id');
    if (error) throw error;
    if (!data || data.length === 0) {
      throw new ConflictException('Pedido já foi pego por outro motoboy ou não está disponível');
    }
    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
  }

  async reivindicarPedido(pedidoId: number, motoboyId: number) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, restaurant_id')
      .eq('id', pedidoId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado');
    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
    await this.exigirUsaMotoboy(pedido.restaurant_id);

    const { data, error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('restaurant_id', pedido.restaurant_id)
      .in('status', ['ready', 'preparing', 'confirmed'])
      .is('motoboy_id', null)
      .select('id');
    if (error) throw error;
    if (!data || data.length === 0) {
      throw new ConflictException('Pedido não encontrado, já foi atribuído ou não está disponível');
    }
    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
  }

  async confirmarColeta(pedidoId: number, motoboyId: number, barcode: string) {
    const expected = String(pedidoId).padStart(8, '0');
    const scanned = barcode.replace(/\D/g, '').padStart(8, '0');
    if (scanned !== expected) {
      throw new BadRequestException('Código de barras não confere com este pedido');
    }

    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, total, troco_para, payment_method, restaurant_id')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .eq('status', 'motoboy_collecting')
      .maybeSingle();
    if (!pedido) throw new ConflictException('Pedido não está aguardando coleta ou não pertence a você');

    const { error } = await this.supabase.client
      .from('orders')
      .update({ status: 'out_for_delivery', updated_at: new Date().toISOString() })
      .eq('id', pedidoId);
    if (error) throw error;

    const trocoValor = pedido.payment_method === 'cash' && pedido.troco_para > pedido.total
      ? Number(pedido.troco_para) - Number(pedido.total)
      : 0;
    if (trocoValor > 0) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, saidas')
        .eq('restaurant_id', pedido.restaurant_id)
        .eq('status', 'aberto')
        .maybeSingle();
      if (caixa) {
        const saidas = (caixa.saidas ?? []) as any[];
        const novaSaida = {
          descricao: `Troco pedido #${pedidoId}`,
          valor: trocoValor,
          meio: 'dinheiro',
          criado_em: new Date().toISOString(),
        };
        await this.supabase.client
          .from('caixas')
          .update({ saidas: [...saidas, novaSaida] })
          .eq('id', caixa.id);
      }
    }

    return { ok: true, pedido_id: pedidoId, status: 'out_for_delivery', troco: trocoValor };
  }

  async uploadComprovante(pedidoId: number, motoboyId: number, base64: string) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    const matches = base64.match(/^data:(image\/\w+);base64,(.+)$/);
    const mimeType = matches ? matches[1] : 'image/jpeg';
    const raw = matches ? matches[2] : base64;
    const buffer = Buffer.from(raw, 'base64');
    const ext = mimeType === 'image/png' ? 'png' : 'jpg';
    const path = `pedido-${pedidoId}-${Date.now()}.${ext}`;

    const { error: uploadError } = await this.supabase.client.storage
      .from('comprovantes-pix')
      .upload(path, buffer, { contentType: mimeType, upsert: true });
    if (uploadError) throw uploadError;

    const { data: { publicUrl } } = this.supabase.client.storage
      .from('comprovantes-pix')
      .getPublicUrl(path);

    await this.supabase.client
      .from('orders')
      .update({ comprovante_pagamento_url: publicUrl, updated_at: new Date().toISOString() })
      .eq('id', pedidoId);

    return { url: publicUrl };
  }

  private async limiteRevisoesPlataforma(): Promise<number> {
    const { data } = await this.supabase.client
      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
    return (data?.config as Record<string, any>)?.motoboy_limite_revisoes ?? 2;
  }

  async infoMotoboy(motoboyId: number) {
    const { data: mb } = await this.supabase.client
      .from('motoboys')
      .select(
        'id, name, phone, email, foto_perfil_url, precisa_completar_cadastro, status_plataforma, motivo_recusa_plataforma, revisoes_solicitadas',
      )
      .eq('id', motoboyId)
      .maybeSingle();
    if (!mb) return null;

    const { afiliacoes } = await this.minhasAfiliacoes(motoboyId);

    return {
      ...mb,
      foto_perfil_url: await this.signedUrl(mb.foto_perfil_url),
      estabelecimentos: afiliacoes.filter((a: any) => a.status === 'aceito').map((a: any) => a.restaurant),
      limite_revisoes_plataforma: await this.limiteRevisoesPlataforma(),
    };
  }

  // Perfil próprio (nome/telefone/foto) — e-mail não é editável por aqui, é a
  // identidade de login (Supabase Auth); troca de e-mail passa por
  // authService.updateEmail no frontend, e o trigger sync_user_profile_email
  // mantém motoboys.email em dia.
  async atualizarPerfilMotoboy(motoboyId: number, body: { name?: string; phone?: string; foto_perfil?: string }) {
    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');

    const campos: Record<string, any> = {};
    if (body.name !== undefined) {
      if (!body.name.trim()) throw new BadRequestException('Nome não pode ficar em branco');
      campos.name = body.name.trim();
    }
    if (body.phone !== undefined) campos.phone = body.phone || null;
    if (body.foto_perfil) {
      const matches = body.foto_perfil.match(/^data:([\w/+-]+);base64,(.+)$/);
      const mimeType = matches ? matches[1] : 'image/jpeg';
      const raw = matches ? matches[2] : body.foto_perfil;
      const buffer = Buffer.from(raw, 'base64');
      const ext = mimeType === 'image/png' ? 'png' : 'jpg';
      const path = `${motoboyId}/foto-perfil-${Date.now()}.${ext}`;
      const { error: uploadError } = await this.supabase.client.storage
        .from(DOC_BUCKET)
        .upload(path, buffer, { contentType: mimeType, upsert: true });
      if (uploadError) throw uploadError;
      campos.foto_perfil_url = path;
    }
    if (Object.keys(campos).length === 0) return this.infoMotoboy(motoboyId);

    const { error } = await this.supabase.client.from('motoboys').update(campos).eq('id', motoboyId);
    if (error) throw error;
    return this.infoMotoboy(motoboyId);
  }

  // Motoboy recusado pede reavaliação — reabre como pendente. Limitado (config
  // do admin) pra não virar loop infinito de recusa/revisão.
  async solicitarRevisaoPlataforma(motoboyId: number) {
    const { data: mb } = await this.supabase.client
      .from('motoboys')
      .select('status_plataforma, revisoes_solicitadas')
      .eq('id', motoboyId)
      .maybeSingle();
    if (!mb) throw new NotFoundException('Motoboy não encontrado');
    if (mb.status_plataforma !== 'recusado') {
      throw new BadRequestException('Só é possível pedir revisão de um cadastro recusado');
    }

    const limite = await this.limiteRevisoesPlataforma();
    if (mb.revisoes_solicitadas >= limite) {
      throw new ForbiddenException('Limite de pedidos de revisão atingido. Entre em contato com o suporte.');
    }

    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({
        status_plataforma: 'pendente',
        motivo_recusa_plataforma: null,
        revisoes_solicitadas: mb.revisoes_solicitadas + 1,
      })
      .eq('id', motoboyId)
      .select('id, status_plataforma, revisoes_solicitadas')
      .maybeSingle();
    if (error) throw error;
    return data;
  }

  // ── Ganhos / comissões ───────────────────────────────────────────────

  async ganhosResumo(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_comissoes')
      .select('restaurant_id, comissao_valor, criado_em, restaurant:restaurants(name)')
      .eq('motoboy_id', motoboyId);
    if (error) throw error;

    const porRestaurante = new Map<number, { restaurant_id: number; nome: string; total: number; entregas: number }>();
    for (const row of data ?? []) {
      const atual = porRestaurante.get(row.restaurant_id) ?? {
        restaurant_id: row.restaurant_id,
        nome: (row as any).restaurant?.name ?? `Estabelecimento #${row.restaurant_id}`,
        total: 0,
        entregas: 0,
      };
      atual.total += Number(row.comissao_valor);
      atual.entregas += 1;
      porRestaurante.set(row.restaurant_id, atual);
    }

    const resumo = [...porRestaurante.values()].sort((a, b) => b.total - a.total);
    const totalGeral = resumo.reduce((acc, r) => acc + r.total, 0);

    // "Hoje" pra aba Financeiro do motoboy acompanhar a produção do dia — mesmo corte de
    // data (início do dia local) usado em relatorioFretes.
    const inicioHoje = new Date();
    inicioHoje.setHours(0, 0, 0, 0);
    const hojeRows = (data ?? []).filter((row: any) => new Date(row.criado_em) >= inicioHoje);
    const hoje = {
      entregas: hojeRows.length,
      total: hojeRows.reduce((acc: number, r: any) => acc + Number(r.comissao_valor), 0),
    };

    return { resumo, total_geral: totalGeral, hoje };
  }

  // Produção por dia pra aba Financeiro do motoboy — mesmo padrão de agrupamento por dia
  // usado em relatorioFretes (por_dia). Sem de/ate (uso original, antes do filtro de
  // período), cai no default de últimos 14 dias.
  async ganhosPorDia(motoboyId: number, restaurantId?: number, de?: string, ate?: string) {
    let query = this.supabase.client
      .from('motoboy_comissoes')
      .select('comissao_valor, criado_em')
      .eq('motoboy_id', motoboyId);

    if (de && ate) {
      query = query.gte('criado_em', de).lte('criado_em', ate);
    } else {
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - 14);
      cutoff.setHours(0, 0, 0, 0);
      query = query.gte('criado_em', cutoff.toISOString());
    }
    if (restaurantId) query = query.eq('restaurant_id', restaurantId);

    const { data, error } = await query;
    if (error) throw error;

    const porDia: Record<string, { dia: string; data: string; entregas: number; total: number }> = {};
    for (const row of (data ?? []) as any[]) {
      const d = new Date(row.criado_em);
      const chave = d.toISOString().slice(0, 10);
      if (!porDia[chave]) {
        porDia[chave] = { dia: d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }), data: chave, entregas: 0, total: 0 };
      }
      porDia[chave].entregas += 1;
      porDia[chave].total += Number(row.comissao_valor);
    }

    return { por_dia: Object.values(porDia).sort((a, b) => (a.data < b.data ? 1 : -1)) };
  }

  async ganhosHistorico(motoboyId: number, restaurantId?: number, de?: string, ate?: string) {
    let query = this.supabase.client
      .from('motoboy_comissoes')
      .select('id, restaurant_id, pedido_id, tipo, distancia_km, frete_repassado, valor_base, comissao_valor, status, criado_em, restaurant:restaurants(name)')
      .eq('motoboy_id', motoboyId)
      .order('criado_em', { ascending: false });

    if (restaurantId) query = query.eq('restaurant_id', restaurantId);
    if (de && ate) {
      // Filtro de período explícito substitui o limite de "últimas 100" — o usuário
      // pediu um recorte, não uma amostra recente.
      query = query.gte('criado_em', de).lte('criado_em', ate);
    } else {
      query = query.limit(100);
    }

    const { data, error } = await query;
    if (error) throw error;
    return { historico: data ?? [] };
  }

  // ── Admin: aprovação de cadastro de motoboy pela plataforma ─────────

  async listarMotoboysAdmin(status?: string) {
    let query = this.supabase.client
      .from('motoboys')
      .select('id, name, phone, email, foto_perfil_url, status_plataforma, motivo_recusa_plataforma, aprovado_em, created_at')
      .order('created_at', { ascending: false });
    if (status) query = query.eq('status_plataforma', status);

    const { data, error } = await query;
    if (error) throw error;

    return {
      motoboys: await Promise.all(
        (data ?? []).map(async (m: any) => ({ ...m, foto_perfil_url: await this.signedUrl(m.foto_perfil_url) })),
      ),
    };
  }

  async detalheMotoboyAdmin(motoboyId: number) {
    const { data: mb, error } = await this.supabase.client
      .from('motoboys')
      .select(
        'id, name, phone, email, foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url, status_plataforma, motivo_recusa_plataforma, aprovado_em, created_at, revisoes_solicitadas',
      )
      .eq('id', motoboyId)
      .maybeSingle();
    if (error) throw error;
    if (!mb) throw new NotFoundException('Motoboy não encontrado');

    return {
      ...mb,
      foto_perfil_url: await this.signedUrl(mb.foto_perfil_url),
      documento_frente_url: await this.signedUrl(mb.documento_frente_url),
      documento_verso_url: await this.signedUrl(mb.documento_verso_url),
      comprovante_endereco_url: await this.signedUrl(mb.comprovante_endereco_url),
    };
  }

  async aprovarMotoboyAdmin(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({ status_plataforma: 'aprovado', motivo_recusa_plataforma: null, aprovado_em: new Date().toISOString() })
      .eq('id', motoboyId)
      .select('id, name, status_plataforma')
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Motoboy não encontrado');
    return data;
  }

  async recusarMotoboyAdmin(motoboyId: number, motivo?: string) {
    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({ status_plataforma: 'recusado', motivo_recusa_plataforma: motivo ?? null, aprovado_em: null })
      .eq('id', motoboyId)
      .select('id, name, status_plataforma')
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Motoboy não encontrado');
    return data;
  }
}

